    i := i + 1;
  }

  // Apply the lemma to help verification
  SumIntsFormula(n);
}

method Main() {
  var n := 5;
  var result := SumIntsLoop(n);
  print "Sum of integers from 0 to ", n, " is: ", result, "\n";

  // Verify for a few values
  var r0 := SumIntsLoop(0);
  assert r0 == 0;

  var r1 := SumIntsLoop(1);
  assert r1 == 1;

  var r10 := SumIntsLoop(10);
  assert r10 == 55;
}
